code.css:
.container_1703001 {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.card_1703001 {
  background: rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 50%;
  padding: 60px;
  text-align: center;
  box-shadow: 0 20px 60px rgba(0,0,0,0.5), 0 0 40px rgba(100, 120, 255, 0.15);
  width: 380px;
  height: 380px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  animation: fadeIn_1703001 0.6s ease;
  box-sizing: border-box;
}

@keyframes fadeIn_1703001 {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

.emoji_1703001 {
  font-size: 56px;
  margin-bottom: 12px;
  display: inline-block;
  animation: float_1703001 3s ease-in-out infinite;
}

@keyframes float_1703001 {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-8px); }
}

.title_1703001 {
  font-size: 1.7rem;
  color: #e0e0ff;
  margin: 0 0 8px 0;
  font-weight: 700;
}

.subtitle_1703001 {
  font-size: 0.8rem;
  color: #a0a8cc;
  line-height: 1.5;
  margin: 0 0 20px 0;
}

.btn_1703001 {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  border: none;
  padding: 10px 26px;
  border-radius: 50px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 15px rgba(102, 126, 234, 0.4);
}

.btn_1703001:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(102, 126, 234, 0.5);
}

.btn_1703001:active {
  transform: translateY(0);
}

code.js:
function handleClick_1703001() {
  const btn = document.querySelector('.btn_1703001');
  const title = document.querySelector('.title_1703001');
  const subtitle = document.querySelector('.subtitle_1703001');
  const emoji = document.querySelector('.emoji_1703001');

  if (btn && title && subtitle && emoji) {
    btn.textContent = '🚀 Ready!';
    btn.style.background = 'linear-gradient(135deg, #11998e, #38ef7d)';
    title.textContent = 'You\'re all set!';
    subtitle.textContent = 'Start editing the code and watch the magic happen in real time.';
    emoji.textContent = '⭐';
  }
}

